def q(s): return '"' + s.replace('"', '\\"') + '"'
y = ["# Freds Pizzeria (Fared Restaurang), Vattugatan 12, Hässleholm: meny för massimport.",
     "# Källa: foodora (foodora.se/restaurant/rd9y), avläst 2026-10-27. Ordinarie priser, inte foodoras 30 %-kampanj.",
     "# Tillvalen följer Palmyras uppsättning: få val blir bildrutor (images.json), extra pålägg är en lista.",
     "# ANTAGET: Familj +110 kr och priserna för extra pålägg (Palmyras), eftersom foodora inte visar tillval när restaurangen är stängd.",
     "extraGroups:"]
for name, typ, req, mx, opts in groups:
    y += [f"  - name: {q(name)}", f"    type: {typ}", f"    required: {'true' if req else 'false'}"] + ([f"    max: {mx}"] if mx else []) + ["    options:"]
    y += [f"      - {{ name: {q(n)}, price: {p} }}" for n, p, _ in opts]
y.append("\ncategories:")
images = {"_kommentar": "Sökvägar relativt apps/web/public/demo/freds-pizzeria/img. Rätterna är genererade studiofoton (Nano Banana 2) med Palmyras foton som referens. Pizzor ligger på samma runda valnötsbräda och övriga rätter på samma vita tallrik, på mörk ek. Dryckerna är Palmyras och Wanthais produktbilder. Saknade drycker är genererade i samma stil.",
          "restaurant": {"logo": "logo-square.webp", "hero": "hero.webp"}, "categories": {}, "products": {}, "boxImageGroups": {}}
PIZZA_EXTRAS = '[Storlek, Extra pålägg, "Sås i burk", Lägg till tillbehör, Lägg till dryck]'
for cat, items in pizzas.items():
    y += [f"  - name: {q(cat)}", "    products:"]
    images["categories"][cat] = f"dishes/{items[0][3]}.webp"
    for n, p, d, img in items:
        ex = PIZZA_EXTRAS if cat != "Inbakade pizzor" else '[Extra pålägg, "Sås i burk", Lägg till tillbehör, Lägg till dryck]'
        y += [f"      - name: {q(n)}", f"        description: {q(d)}", f"        price: {p}", f"        extras: {ex}"]
        images["products"][n] = f"dishes/{img}.webp"
for cat, items in other.items():
    y += [f"  - name: {q(cat)}", "    products:"]
    images["categories"][cat] = f"dishes/{items[0][3]}.webp"
    for n, p, d, img, sas in items:
        if cat in ("Tillbehör", "Såser"): ex = None
        elif sas: ex = '["Välj sås (ingår)", "Sås i burk", Lägg till tillbehör, Lägg till dryck]'
        else: ex = '["Sås i burk", Lägg till tillbehör, Lägg till dryck]'
        y += [f"      - name: {q(n)}", f"        description: {q(d)}", f"        price: {p}"] + ([f"        extras: {ex}"] if ex else [])
        images["products"][n] = f"dishes/{img}.webp"
y += ["  - name: Drycker", "    products:"]
images["categories"]["Drycker"] = "drinks/coca-cola-33.webp"
for n, p, img in drinks:
    y += [f"      - {{ name: {q(n)}, description: \"\", price: {p} }}"]
    images["products"][n] = f"drinks/{img}.webp"
for name, typ, req, mx, opts in groups:
    if all(o[2] for o in opts):
        images["boxImageGroups"][name] = {"allowQuantity": typ == "checkbox", "extras": {n: f for n, _, f in opts}}
open("menu.yaml", "w").write("\n".join(y) + "\n")
json.dump(images, open("images.json", "w"), ensure_ascii=False, indent=2)
print(sum(len(v) for v in pizzas.values()), "pizzor,", sum(len(v) for v in other.values()), "övriga,", len(drinks), "drycker")
